package java_basics;

public class Swap {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=70;
		int b=80;
		int temp;
		
		System.out.println("Before Swapping");
		System.out.println("a="+a);
		System.out.println("b="+b);
		
		temp=a;
		a=b;
		b=temp;
		
		System.out.println("After Swapping");
		System.out.println("a="+a);
		System.out.println("b="+b);

	}

}
